using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class EvalTests
{
    private static ReportingConfiguration? s_reportingConfiguration;
    private static IChatClient? s_chatClient;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        // Use an environment variable or configuration to point to the chat endpoint.
        // For local dev, you can set AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_DEPLOYMENT.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
            ?? "chat";

        s_chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deployment)
            .AsIChatClient();

        var chatConfig = new ChatConfiguration(s_chatClient);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine("..", ".eval-reports"),
            evaluators: evaluators,
            chatConfiguration: chatConfig);
    }

    [TestMethod]
    public async Task Chat_responds_coherently()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_coherently));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await s_chatClient!.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        Assert.IsNotNull(response.Text);
        Assert.IsTrue(response.Text.Length > 0);
    }

    [TestMethod]
    public async Task Chat_follows_instructions()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_follows_instructions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in exactly one sentence."),
            new(ChatRole.User, "Explain what an eval is in the context of AI applications.")
        };

        var response = await s_chatClient!.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        Assert.IsNotNull(response.Text);
        Assert.IsTrue(response.Text.Length > 0);
    }
}

